(()=>{const s=document.createElement('style');s.textContent=`.microscope-instruction{position:relative;z-index:6;margin:0 auto 24px;width:max-content;max-width:calc(100% - 32px);padding:10px 18px;border:2px solid #ffffffb8;border-radius:999px;background:#063b78a8;backdrop-filter:blur(10px);color:#fff;text-align:center;font-size:14px;font-weight:900;box-shadow:0 0 18px #00d9ff66}.microscope-lens{position:fixed;z-index:10000;width:min(330px,72vw);height:min(330px,72vw);border-radius:50%;pointer-events:none;opacity:0;transform:translate(-50%,-50%) scale(.65);transition:.2s;background:radial-gradient(circle at 38% 34%,#ffffff24 0 7%,transparent 22%),radial-gradient(circle,transparent 58%,#001b3a99 78%,#001020e8 100%);border:7px solid #fff;box-shadow:0 0 0 7px #008cff,0 0 42px #00d9ff,0 0 58px #ff8a0080}.microscope-lens:before,.microscope-lens:after{content:"";position:absolute;background:#ffffffa8}.microscope-lens:before{width:1px;height:100%;left:50%}.microscope-lens:after{height:1px;width:100%;top:50%}.microscope-lens.active{opacity:1;transform:translate(-50%,-50%) scale(1)}.microscope-label{position:absolute;left:50%;bottom:12%;transform:translateX(-50%);padding:5px 10px;border-radius:999px;background:#001f45df;color:#fff;font-size:11px;font-weight:900;letter-spacing:1px;white-space:nowrap}.microscope-target{position:relative;z-index:10001!important;transform:scale(1.18)!important;transform-origin:center!important;filter:contrast(1.08) drop-shadow(0 0 8px #fff) drop-shadow(0 0 16px #00d9ff)!important;transition:.2s!important}@media(max-width:760px){.microscope-instruction{font-size:12px;padding:8px 13px}.microscope-target{transform:scale(1.1)!important}}`;document.head.appendChild(s);const hero=document.querySelector('.hero');if(hero){const note=document.createElement('div');note.className='microscope-instruction';note.textContent='Hold the screen or mouse to enter microscope mode.';hero.insertBefore(note,hero.firstChild)}const lens=document.createElement('div');lens.className='microscope-lens';lens.innerHTML='<span class="microscope-label">MICROSCOPE MODE</span>';document.body.appendChild(lens);let holding=false,target=null;const selector='h1,h2,h3,p,.eyebrow,.kicker,.credit-label,.institution,.hero-verse,.molecule-link,.paper-button,.comic-panel span,.bottom-band,footer';function move(e){lens.style.left=e.clientX+'px';lens.style.top=e.clientY+'px';if(!holding)return;const el=document.elementFromPoint(e.clientX,e.clientY),next=el&&el.closest(selector);if(next!==target){if(target)target.classList.remove('microscope-target');target=next;if(target)target.classList.add('microscope-target')}}function start(e){if(e.button!==undefined&&e.button!==0)return;if(e.target.closest('a,button,.info-card'))return;holding=true;move(e);lens.classList.add('active')}function stop(){holding=false;lens.classList.remove('active');if(target){target.classList.remove('microscope-target');target=null}}addEventListener('pointermove',move,{passive:true});addEventListener('pointerdown',start,{passive:true});addEventListener('pointerup',stop,{passive:true});addEventListener('pointercancel',stop,{passive:true})})();